# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatorMixin, TimestampMixin


class CompendiumM2mPoiRegion(TimestampMixin, CreatorMixin, Base):
    __tablename__ = "compendium_m2m_poi_region"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    poi_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("compendium_cat_poi.id", ondelete="CASCADE"),
        nullable=False,
        description=(
            "Foreign key to the point of interest in this POI-region "
            "association. References compendium_cat_poi.id with ON DELETE "
            "CASCADE."
        ),
    )
    region_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("compendium_cat_region.id", ondelete="CASCADE"),
        nullable=False,
        description=(
            "Foreign key to the geographic region in this POI-region "
            "association. References compendium_cat_region.id with ON DELETE "
            "CASCADE."
        ),
    )
    slot_position: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        description=(
            "Integer defining the display order of this region relative to "
            "other regions linked to the same POI. Lower values appear first."
        ),
    )
